for name,title,note in [('final-current-12s.png','Замковый участок','Игровая камера последней версии.'),('final-current-40s.png','Поворот у лавы','Игровая камера; полотно и ускорители исходные.'),('final-current-80s.png','Верхняя часть маршрута','Полный круг проходит исходные подъёмы и мосты.'),('final-current-150s.png','Результат итогового круга','Естественный финиш; без принудительной победы.'),('final-320s.png','Проверка двух кругов','Версия до замены дымовых мешей и уменьшения пяти дымовых эффектов; дорога, физика и игровые данные совпадают.'),('preview-castle-wide.png','Каменный замок','Камера осмотра в игровом движке; источник превью.'),('section-volcano.png','Вулканическое окружение','Камера осмотра в игровом движке.'),('section-bridge.png','Верхний мост','Камера осмотра в игровом движке.')]:
 p=r/'screenshots'/name
 if p.is_file():shutil.copy2(p,out/'screenshots'/name);shots.append((name,title,note))
